const SUBJECTS=window.STUDY_DATA;
const ALL=SUBJECTS.flatMap(s=>s.questions.map(q=>({...q,subject:s.id})));
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>new Intl.NumberFormat('ur-PK',{numberingSystem:'arabext'}).format(n);
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',book:'M12 6c-3-2-7-2-10-1v15c3-1 7-1 10 1 3-2 7-2 10-1V5c-3-1-7-1-10 1Zm0 0v15',bookmark:'M6 3h12v19l-6-4-6 4Z',chart:'M4 3v17h17M8 16v-4m5 4V7m5 9V4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Zm-2-6h4l1 3 3 1 3 1v4l-2 2-1 3 1 3-3 2-3-1-3 1-3-2 1-3-1-3-2-2V7l3-1 1-3Z',mic:'M9 5a3 3 0 0 1 6 0v7a3 3 0 0 1-6 0ZM5 11v1a7 7 0 0 0 14 0v-1M12 19v3m-4 0h8',search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',moon:'M21 13A9 9 0 0 1 11 3 9 9 0 1 0 21 13Z',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Zm0-6v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',arrow:'M19 12H5m6-6-6 6 6 6',check:'m5 12 4 4L19 6',layers:'m12 3 10 6-10 6L2 9Zm-9 12 9 5 9-5M3 19l9 5 9-5',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6Zm-4 10 3 3 5-6',scale:'M12 3v18M7 21h10M4 6h16M6 6l-4 9h8Zm12 0-4 9h8',globe:'M21 12A9 9 0 1 1 3 12a9 9 0 0 1 18 0ZM3 12h18M12 3c-5 5-5 13 0 18 5-5 5-13 0-18Z',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3Z',compass:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Zm-5-4-3 5-5 3 3-5Z',menu:'M4 6h16M4 12h16M4 18h16',info:'M12 11v6m0-10v1M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z',focus:'M3 8V3h5m8 0h5v5M3 16v5h5m8 0h5v-5',clock:'M12 8v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',repeat:'M3 8h15l-4-4m4 4-4 4M21 16H6l4 4m-4-4 4-4',close:'m6 6 12 12M6 18 18 6',copy:'M8 8h12v13H8ZM4 16H2V2h13v2'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.book}"/></svg>`;
function readStore(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
let progress=readStore('alhayat-progress',{}), bookmarks=readStore('alhayat-bookmarks',[]),notes=readStore('alhayat-notes',{}),settings={theme:'light',font:'nastaliq',size:25,highlight:true,goal:5,...readStore('alhayat-settings',{})};
if(!settings.fontRevision){settings.font='nastaliq';settings.size=25;settings.fontRevision=2;save('settings',settings)}
if(!progress||Array.isArray(progress)||typeof progress!=='object')progress={};if(!Array.isArray(bookmarks))bookmarks=[];if(!notes||typeof notes!=='object')notes={};
let last=readStore('alhayat-last',null),history=readStore('alhayat-history',{}),current=null,revealed=false,focus=false,practicePool=[],practiceIndex=0,timer=null,remaining=90,activeFilter='all';
const getSub=id=>SUBJECTS.find(s=>s.id===id),getQ=id=>ALL.find(q=>q.id===id),today=()=>new Date().toLocaleDateString('en-CA');
const isKnown=q=>progress[q.id]?.status==='known';
const due=q=>progress[q.id]?.due && progress[q.id].due<=Date.now();
function save(key,v){try{localStorage.setItem('alhayat-'+key,JSON.stringify(v));return true}catch{toast('براؤزر میں محفوظ کرنے کی گنجائش دستیاب نہیں۔');return false}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function applySettings(){document.documentElement.dataset.theme=settings.theme;document.documentElement.dataset.font=settings.font;document.documentElement.style.setProperty('--reading-size',settings.size+'px');$('#theme-btn').innerHTML=icon(settings.theme==='dark'?'sun':'moon');$('#theme-btn').setAttribute('aria-label',settings.theme==='dark'?'دن کا انداز':'رات کا انداز')}
function percent(s){const qs=s?s.questions:ALL;return Math.round(qs.filter(isKnown).length/qs.length*100)}
function updateProgress(){const p=percent();$('#side-percent').textContent=num(p)+'٪';$('#side-progress-bar').style.width=p+'%';$('#side-progress-label').textContent=`${num(ALL.filter(isKnown).length)} از ${num(ALL.length)} سوالات کی تیاری مکمل`}
function initNav(){const nav=[['home','home','مطالعے کا آغاز'],['review','repeat','دہرائی'],['practice','mic','انٹرویو مشق'],['bookmarks','bookmark','محفوظ سوالات'],['progress','chart','میری پیش رفت'],['settings','settings','ترتیبات'],['about','info','تعارف']];$('#main-nav').innerHTML=nav.map(([id,ic,t])=>`<a href="#${id}" data-nav="${id}">${icon(ic)}<span>${t}</span>${id==='review'?'<b class="nav-badge" id="due-count"></b>':''}</a>`).join('');$('#subject-nav').innerHTML=SUBJECTS.map(s=>`<a href="#subject/${s.id}" data-sub="${s.id}" style="--subject:${s.color}"><span class="subject-dot"></span><span>${s.title}</span><small>${num(s.questions.length)}</small></a>`).join('');$('#search-subject').innerHTML+='<optgroup label="مضامین">'+SUBJECTS.map(s=>`<option value="${s.id}">${s.title}</option>`).join('')+'</optgroup>';$('#menu-btn').innerHTML=icon('menu');$('#search-icon').innerHTML=icon('search');$('#dialog-search-icon').innerHTML=icon('search')}
function syncMenuA11y(){ $('#sidebar').inert=matchMedia('(max-width:850px)').matches&&!document.body.classList.contains('menu-open') }
function closeMenu(){document.body.classList.remove('menu-open');$('#menu-btn').setAttribute('aria-expanded','false');syncMenuA11y()}
function setActive(route,sid){$$('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===route));$$('[data-sub]').forEach(a=>a.classList.toggle('active',a.dataset.sub===sid));const n=ALL.filter(due).length;$('#due-count').textContent=n?num(n):'';$('#due-count').hidden=!n;updateProgress()}
function eyebrow(t){return `<div class="eyebrow"><i></i>${t}</div>`}
function heading(k,t,sub=''){return `<div class="page-heading">${eyebrow(k)}<h1>${t}</h1>${sub?`<p>${sub}</p>`:''}</div>`}
function empty(title,desc,action='مضامین دیکھیے',url='#home'){return `<div class="empty-state">${icon('book')}<h2>${title}</h2><p>${desc}</p><a class="btn primary" href="${url}">${action}${icon('arrow')}</a></div>`}
function home(){const resume=last&&getQ(last)?getQ(last):ALL[0],s=getSub(resume.subject);const mastered=ALL.filter(isKnown).length;const dayCount=history[today()]?.length||0;$('#main').innerHTML=`
<section class="welcome"><div>${eyebrow('الحیات علمی رفاقت')}<h1>علم کو سمجھیے۔<br><span>اعتماد سے گفتگو کیجیے۔</span></h1><p>علومِ اسلامیہ کا مربوط مطالعہ، بامقصد دہرائی اور انٹرویو کی تیاری۔</p><div class="welcome-actions"><a class="btn primary" href="#read/${resume.subject}/${resume.id}">${last?'مطالعہ جاری رکھیے':'مطالعہ شروع کیجیے'}${icon('arrow')}</a><a class="text-link" href="#practice">انٹرویو کی مشق ${icon('mic')}</a></div></div><div class="hero-art" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="art-tile art-back"></div><div class="art-tile art-main">${icon('book')}<span>علم • فہم • عمل</span></div><div class="art-caption">اپنے علمی سفر کا اگلا قدم</div><span class="art-star star-one">✦</span><span class="art-star star-two">✦</span></div></section>
<div class="stat-strip"><div><b>${num(SUBJECTS.length)}</b><span>بنیادی مضامین</span></div><div><b>${num(ALL.length)}</b><span>منتخب علمی سوالات</span></div><div><b>${num(mastered)}</b><span>تیار شدہ سوالات</span></div><div><b>${num(percent())}<small>٪</small></b><span>آپ کی پیش رفت</span></div></div>
<section class="subjects-section"><div class="section-title"><div><h2>آج کیا پڑھنا چاہیں گے؟</h2><p>ہر مضمون ایک نیا زاویۂ فہم</p></div><span class="pill">۸ علمی راستے</span></div><div class="subject-grid">${SUBJECTS.map((sub,i)=>`<a class="subject-card" href="#subject/${sub.id}" style="--subject:${sub.color};--delay:${i*30}ms"><div class="subject-card-top"><span class="subject-symbol">${icon(sub.icon)}</span><span class="subject-number" dir="ltr">0${i+1}</span></div><h3>${sub.title}</h3><p>${sub.subtitle}</p><div class="subject-card-bottom"><span>${num(sub.questions.length)} سوالات</span><span class="card-arrow">${icon('arrow')}</span></div><div class="card-progress"><i style="width:${percent(sub)}%"></i></div></a>`).join('')}</div></section>
<div class="home-bottom"><section class="continue-card"><div class="section-title"><h2>${last?'جہاں سے چھوڑا تھا':'پہلا علمی قدم'}</h2><span class="mini-label" style="color:${s.color}">${s.title}</span></div><div class="continue-body"><span class="question-kicker">سوال ${num(resume.order)} • ${esc(resume.groupTitle)}</span><h3>${esc(resume.q)}</h3><p>${esc(resume.a.split('\n\n')[0])}</p><a class="text-link" href="#read/${resume.subject}/${resume.id}">مکمل جواب پڑھیے ${icon('arrow')}</a></div></section><section class="daily-card"><span class="daily-icon">${icon('sun')}</span><h2>روزانہ، تھوڑا مگر مسلسل</h2><p>آج ${num(settings.goal)} سوالات کی تیاری کا ہدف رکھیے۔ پہلے سمجھیے، پھر اپنے الفاظ میں جواب دیجیے۔</p><div class="daily-count"><b>${num(dayCount)}</b><span>/ ${num(settings.goal)} سوالات</span></div><div class="progress-track"><i style="width:${Math.min(100,dayCount/settings.goal*100)}%"></i></div><a href="#review" class="text-link">دہرائی کی طرف ${icon('arrow')}</a></section></div>`}
function subject(id){const s=getSub(id);if(!s)return notFound();$('#main').style.setProperty('--subject',s.color);const done=s.questions.filter(isKnown).length;$('#main').innerHTML=`${heading('منتخب مضمون',s.title,s.subtitle)}<div class="course-summary"><span class="subject-symbol">${icon(s.icon)}</span><div><b>${num(s.questions.length)} سوالات <em>•</em> ${num(s.groups.length)} حصے</b><p>${num(done)} سوالات تیار — ${num(percent(s))}٪ پیش رفت</p></div><a class="btn primary" href="#read/${s.id}/${(s.questions.find(q=>!isKnown(q))||s.questions[0]).id}">مطالعہ جاری رکھیے ${icon('arrow')}</a></div><div class="course-tools"><label class="inline-search">${icon('search')}<input id="course-search" type="search" placeholder="اس مضمون میں تلاش کریں" aria-label="اس مضمون میں تلاش"></label><button class="btn subtle" id="course-practice">${icon('mic')}اسی مضمون کی مشق</button><button class="btn subtle" id="course-sources">${icon('book')}مراجع</button></div><div class="question-filter"><button data-filter="all" class="active">تمام سوالات</button><button data-filter="new">باقی سوالات</button><button data-filter="known">تیار شدہ</button><button data-filter="review">مزید دہرائی</button></div><div id="course-list"></div><details class="source-details" id="course-references"><summary>مضمون کے مراجع اور اصل مواد</summary><p>${esc(s.referenceNote||'اصل فراہم کردہ علمی مواد؛ متعلقہ سوالات کے ساتھ مزید مطالعہ کے مراجع شامل ہیں۔')}</p><a class="text-link" href="data/${encodeURIComponent(s.sourceFile)}" download>اصل JSON ڈاؤن لوڈ کریں ${icon('download')}</a>${renderBibliography(s)}</details>`;activeFilter='all';renderCourseList(s);$('#course-search').oninput=()=>renderCourseList(s);$$('[data-filter]').forEach(b=>b.onclick=()=>{activeFilter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));renderCourseList(s)});$('#course-practice').onclick=()=>startPractice(s.id);$('#course-sources').onclick=()=>{$('#course-references').open=true;$('#course-references').scrollIntoView({behavior:'smooth'})}}
const normalize=s=>String(s).normalize('NFKC').replace(/[\u064B-\u065F\u0670\u06D6-\u06ED\u200c\u200d\u0640]/g,'').replace(/[يى]/g,'ی').replace(/ك/g,'ک').replace(/[أإآ]/g,'ا').replace(/ۀ/g,'ہ').toLowerCase();
function matches(q,text){const tokens=normalize(text).trim().split(/\s+/).filter(Boolean);const hay=normalize([q.q,q.a,q.title,q.groupTitle].join(' '));return tokens.every(t=>hay.includes(t))}
function renderCourseList(s){const text=$('#course-search').value;const filtered=s.questions.filter(q=>matches(q,text)&&(activeFilter==='all'||activeFilter==='known'&&isKnown(q)||activeFilter==='new'&&!isKnown(q)||activeFilter==='review'&&progress[q.id]?.status==='review'));$('#course-list').innerHTML=filtered.length?s.groups.map(g=>{const qs=filtered.filter(q=>q.groupId===g.id);return qs.length?`<section class="question-group"><div class="group-heading"><span>${esc(g.title)}</span><small>${num(qs.length)} سوالات</small></div>${qs.map(q=>questionRow(q,s)).join('')}</section>`:''}).join(''):empty('کوئی سوال نہیں ملا','تلاش کے الفاظ یا سوالات کا انتخاب بدل کر دیکھیے۔','تمام مضامین','#home')}
function questionRow(q,s){return `<a class="question-row" href="#read/${s.id}/${q.id}"><span class="row-number ${isKnown(q)?'done':''}">${isKnown(q)?icon('check'):num(q.order)}</span><span class="row-text">${esc(q.q)}<small>${progress[q.id]?.status==='review'?'دہرائی درکار ہے':esc(q.title||q.topic||'')}</small></span>${bookmarks.includes(q.id)?icon('bookmark','row-bookmark'):''}<span class="row-arrow">${icon('arrow')}</span></a>`}
function renderBibliography(s){const arr=Array.isArray(s.bibliography)?s.bibliography:[];return arr.length?`<ul class="bibliography">${arr.map(r=>`<li><b>${esc(typeof r==='string'?r:r.title||r.book||'')}</b>${r.author?` — ${esc(r.author)}`:''}${r.focus?`<p>${esc(r.focus)}</p>`:''}${safeURL(r.url)?`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">حوالہ دیکھیے ↗</a>`:''}</li>`).join('')}</ul>`:''}
function safeURL(v){try{return ['https:','http:'].includes(new URL(v).protocol)}catch{return false}}
const TERMS=['توحید','عقیدہ','ایمان','قرآن','سنت','اجتہاد','اجماع','قیاس','اختلافِ تنوع','اختلافِ تضاد','اسبابِ نزول','علمی دیانت','سیاق','تفسیر','تدبر','تقدیر','رسالت','ختمِ نبوت','شریعت','مقاصد','توحیدِ','حدیث','سیرت','عقل','علمِ کلام','تکفیر','اسناد','روایت','توحیدِ الوہیت'];
function rich(text,arabicSpans=[]){
 const spans=[...new Set(arabicSpans)].filter(x=>text.includes(x)).sort((a,b)=>b.length-a.length);
 const escapeReg=x=>x.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
 function urdu(t){let html=esc(t).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');if(settings.highlight){const found=TERMS.filter(k=>t.includes(k)).sort((a,b)=>b.length-a.length).slice(0,5);if(found.length)html=html.replace(new RegExp('('+found.map(escapeReg).join('|')+')','g'),'<mark>$1</mark>')}return html}
 if(!spans.length)return urdu(text);
 const expression=new RegExp('('+spans.map(escapeReg).join('|')+')','g');
 return text.split(expression).map(part=>spans.includes(part)?'<strong class="arabic-quote" lang="ar" dir="rtl">'+esc(part)+'</strong>':urdu(part)).join('');
}
function refText(r){return typeof r==='string'?r: r.title||r.citation||r.reference||r.text||r.book||JSON.stringify(r)}
function referencePanel(q){let readings=Array.isArray(q.further_reading)?q.further_reading:q.further_reading?[q.further_reading]:[];let refs=Array.isArray(q.references)?q.references:q.references?[q.references]:[];return readings.length||refs.length?`<details class="references"><summary>${icon('book')}مراجع اور مزید مطالعہ <span>+</span></summary><div>${readings.map(r=>`<p>${esc(refText(r))}</p>`).join('')}${refs.map(r=>`<p>${typeof r==='object'&&safeURL(r.url)?`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(refText(r))} ↗</a>`:esc(refText(r))}</p>`).join('')}</div></details>`:''}
function answerHTML(q){return `<div class="answer-text">${q.a.split(/\n\s*\n/).filter(Boolean).map(p=>`<p>${rich(p,q.arabic_spans||[])}</p>`).join('')}</div>${referencePanel(q)}`}
function reader(sid,qid){const s=getSub(sid),q=getQ(qid);if(!s||!q||q.subject!==sid)return notFound();current=q;last=q.id;save('last',last);$('#main').style.setProperty('--subject',s.color);const idx=s.questions.findIndex(x=>x.id===qid);$('#main').innerHTML=`<div class="reader-top"><a class="breadcrumb" href="#subject/${sid}">${icon('arrow')} ${s.title}</a><div class="reader-top-actions"><button class="btn subtle" id="focus-toggle" aria-label="یکسو مطالعہ">${icon('focus')}<span>یکسو مطالعہ</span></button><button class="btn subtle mobile-outline-button" id="outline-toggle" aria-label="فہرستِ سوالات کھولیں">${icon('layers')}فہرست</button><button class="icon-button" id="reader-search" aria-label="تلاش">${icon('search')}</button></div></div><div class="reader-layout"><article class="reader-card"><div class="reader-meta"><span class="pill subject-pill">${esc(q.groupTitle)}</span><span>سوال ${num(q.order)} از ${num(s.questions.length)}</span></div><div class="reader-question"><div class="question-tools"><span class="question-kicker">سمجھیے، پھر اپنے الفاظ میں کہیے</span><button class="icon-button bookmark-btn ${bookmarks.includes(q.id)?'selected':''}" id="bookmark-btn" aria-label="سوال محفوظ کریں" aria-pressed="${bookmarks.includes(q.id)}">${icon('bookmark')}</button></div><h1>${esc(q.q)}</h1></div><div class="answer-heading"><span>تفصیلی جواب</span><span class="answer-rule"></span><button class="icon-button" id="copy-answer" aria-label="جواب نقل کریں">${icon('copy')}</button></div>${answerHTML(q)}<div class="recall-prompt">${icon('mic')}<div><b>اب اپنی زبان میں جواب دیجیے</b><p>مرکزی نکتہ، اس کی دلیل اور ایک مثال بیان کیجیے۔</p></div></div><div class="self-assess"><p>اس سوال کی تیاری کیسی رہی؟</p><div><button class="btn assess-review ${progress[q.id]?.status==='review'?'chosen':''}" id="mark-review">${icon('repeat')}مزید دہرائی چاہیے</button><button class="btn assess-known ${isKnown(q)?'chosen':''}" id="mark-known">${icon('check')}اچھی طرح سمجھ لیا</button></div></div><details class="notes-panel" ${notes[q.id]?'open':''}><summary>میرا مختصر نوٹ <span>✎</span></summary><label for="question-note">دلیل، مثال یا وہ نکتہ جو یاد رکھنا ہے</label><textarea id="question-note" rows="3" placeholder="اپنے الفاظ میں لکھیے…">${esc(notes[q.id]||'')}</textarea><small id="note-status">نوٹس اسی براؤزر میں محفوظ ہوتے ہیں۔</small></details><div class="reader-pagination"><a class="btn subtle ${idx===0?'disabled':''}" ${idx>0?`href="#read/${sid}/${s.questions[idx-1].id}"`:'aria-disabled="true"'}>پچھلا سوال</a><span>${num(idx+1)} / ${num(s.questions.length)}</span><a class="btn primary ${idx===s.questions.length-1?'disabled':''}" ${idx<s.questions.length-1?`href="#read/${sid}/${s.questions[idx+1].id}"`:'aria-disabled="true"'}>اگلا سوال ${icon('arrow')}</a></div></article><aside class="reader-outline"><div class="outline-title"><h2>اس مضمون میں</h2><span>${num(percent(s))}٪ مکمل</span></div><div class="progress-track"><i style="width:${percent(s)}%"></i></div><div class="outline-scroll">${s.groups.map(g=>`<details ${g.id===q.groupId?'open':''}><summary>${esc(g.title)}</summary>${s.questions.filter(x=>x.groupId===g.id).map(x=>`<a class="outline-question ${x.id===q.id?'current':''}" href="#read/${sid}/${x.id}" ${x.id===q.id?'aria-current="page"':''}><span>${isKnown(x)?'✓':num(x.order)}</span>${esc(x.title||x.q)}</a>`).join('')}</details>`).join('')}</div><a class="outline-practice" href="#practice">${icon('mic')}اپنے علم کو گفتگو بنائیے</a></aside></div>`;
$('#bookmark-btn').onclick=()=>{toggleBookmark(q.id);$('#bookmark-btn').classList.toggle('selected',bookmarks.includes(q.id));$('#bookmark-btn').setAttribute('aria-pressed',bookmarks.includes(q.id))};$('#mark-review').onclick=()=>assess(q,'review');$('#mark-known').onclick=()=>assess(q,'known');$('#question-note').oninput=e=>{notes[q.id]=e.target.value;save('notes',notes);$('#note-status').textContent='نوٹ محفوظ ہوگیا۔'};$('#copy-answer').onclick=()=>copyText(q.q+'\n\n'+q.a);$('#reader-search').onclick=openSearch;$('#outline-toggle').onclick=()=>{const dlg=$('#outline-dialog');$('#outline-dialog-body').innerHTML=$('.reader-outline').innerHTML;dlg.showModal();$('#outline-dialog-body').onclick=e=>{if(e.target.closest('a'))dlg.close()}};$('#focus-toggle').onclick=()=>{focus=!focus;document.body.classList.toggle('focus-mode',focus);$('#focus-toggle').setAttribute('aria-label',focus?'معمول کا مطالعہ':'یکسو مطالعہ');$('#focus-toggle').innerHTML=icon('focus')+`<span>${focus?'معمول کا مطالعہ':'یکسو مطالعہ'}</span>`}}
function toggleBookmark(id){bookmarks=bookmarks.includes(id)?bookmarks.filter(x=>x!==id):[...bookmarks,id];save('bookmarks',bookmarks);toast(bookmarks.includes(id)?'سوال محفوظ ہوگیا۔':'سوال محفوظ فہرست سے ہٹا دیا گیا۔')}
function assess(q,status){const previous=progress[q.id]||{},box=status==='known'?Math.min(4,(previous.box||0)+1):0;const days=[1,3,7,14,30];progress[q.id]={status,box,due:Date.now()+days[box]*86400000,updated:Date.now()};save('progress',progress);const day=today();history[day]=[...new Set([...(history[day]||[]),q.id])];save('history',history);updateProgress();toast(status==='known'?'تیاری محفوظ — مقررہ وقت پر دوبارہ دیکھیے۔':'دہرائی کی فہرست میں شامل ہوگیا۔');if($('#mark-known')){$('#mark-known').classList.toggle('chosen',status==='known');$('#mark-review').classList.toggle('chosen',status==='review')}const s=getSub(q.subject);if($('.outline-title span'))$('.outline-title span').textContent=num(percent(s))+'٪ مکمل'}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('متن نقل ہوگیا۔')}catch{toast('نقل دستیاب نہیں؛ متن منتخب کرکے نقل کیجیے۔')}}
function collection(type){const list=type==='bookmarks'?ALL.filter(q=>bookmarks.includes(q.id)):ALL.filter(q=>due(q)||progress[q.id]?.status==='review');const bookmark=type==='bookmarks';$('#main').innerHTML=heading(bookmark?'آپ کا ذاتی انتخاب':'تسلسل سے پختگی تک',bookmark?'محفوظ سوالات':'دہرائی کا وقت',bookmark?'اہم سوالات ایک جگہ رکھیے، اور ضرورت پر دوبارہ پڑھیے۔':'وہ سوالات جنہیں آپ نے دہرائی کے لیے چنا، یا جن کی اگلی دہرائی کا وقت آگیا ہے۔')+(list.length?`<div class="collection-head"><span>${num(list.length)} سوالات</span>${!bookmark?'<button class="btn primary" id="review-practice">'+icon('mic')+'ان سوالات کی مشق</button>':''}</div>${SUBJECTS.map(s=>{const qs=list.filter(q=>q.subject===s.id);return qs.length?`<section class="question-group" style="--subject:${s.color}"><div class="group-heading">${s.title}<small>${num(qs.length)}</small></div>${qs.map(q=>questionRow(q,s)).join('')}</section>`:''}).join('')}`:empty(bookmark?'ابھی کوئی محفوظ سوال نہیں':'اس وقت دہرائی کا کوئی سوال نہیں',bookmark?'مطالعے کے دوران بک مارک کے نشان سے سوال محفوظ کیجیے۔':'مطالعہ شروع کریں اور اپنی تیاری کی کیفیت درج کریں۔'));if($('#review-practice'))$('#review-practice').onclick=()=>startPractice('',list)}
function practiceSetup(){current=null;$('#main').innerHTML=heading('علم سے گفتگو تک','انٹرویو کی مشق','پہلے خود جواب دیجیے، پھر اصل جواب سے موازنہ کیجیے۔')+`<section class="practice-setup"><div class="practice-illustration">${icon('mic')}<span>سمجھیے • کہیے • بہتر بنائیے</span></div><h2>اپنی تیاری کو آواز دیجیے</h2><p>ہر سوال پر مرکزی موقف، دلیل اور مثال بیان کرنے کی کوشش کیجیے۔ یہ خود جانچنے کی مشق ہے؛ خودکار نمبر یا ریکارڈنگ نہیں ہوتی۔</p><div class="practice-fields"><label>مضمون<select id="practice-subject"><option value="">تمام مضامین</option>${SUBJECTS.map(s=>`<option value="${s.id}">${s.title}</option>`).join('')}</select></label><label>سوالات کا انتخاب<select id="practice-type"><option value="all">تمام سوالات میں سے</option><option value="new">ابھی باقی سوالات</option><option value="bookmarked">محفوظ سوالات</option><option value="review">دہرائی کے سوالات</option></select></label><label>مشق کی طوالت<select id="practice-length"><option value="5">۵ سوالات</option><option value="10">۱۰ سوالات</option><option value="20">۲۰ سوالات</option></select></label></div><button class="btn primary" id="start-practice">${icon('mic')}مشق شروع کیجیے</button><div class="practice-tip">ہر سوال کے لیے ۹۰ سیکنڈ کا اختیاری ٹائمر دستیاب ہے۔</div></section>`;$('#start-practice').onclick=()=>{let list=ALL.filter(q=>!$('#practice-subject').value||q.subject===$('#practice-subject').value);const type=$('#practice-type').value;list=list.filter(q=>type==='all'||type==='new'&&!isKnown(q)||type==='bookmarked'&&bookmarks.includes(q.id)||type==='review'&&(due(q)||progress[q.id]?.status==='review'));startPractice($('#practice-subject').value,list,Number($('#practice-length').value))}}
function shuffled(arr){const a=[...arr];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function startPractice(sid='',list=null,count=5){clearInterval(timer);practicePool=shuffled(list||ALL.filter(q=>!sid||q.subject===sid)).slice(0,count);practiceIndex=0;if(!practicePool.length){toast('اس انتخاب میں کوئی سوال موجود نہیں۔');return}if(location.hash!=='#practice')historyNavigate('#practice');renderPractice()}
function historyNavigate(hash){window.history.pushState(null,'',hash);setActive(hash.slice(1));closeMenu()}
function renderPractice(){clearInterval(timer);revealed=false;remaining=90;const q=practicePool[practiceIndex];current=q;const s=getSub(q.subject);$('#main').style.setProperty('--subject',s.color);$('#main').innerHTML=`<div class="practice-top"><a class="breadcrumb" href="#practice" id="exit-practice">${icon('close')}مشق ختم کریں</a><span>سوال ${num(practiceIndex+1)} از ${num(practicePool.length)}</span></div><div class="practice-progress"><i style="width:${practiceIndex/practicePool.length*100}%"></i></div><article class="practice-card"><span class="pill subject-pill">${s.title}</span><div class="practice-timer"><span id="timer-label" dir="ltr">01:30</span><button class="btn subtle" id="timer-toggle">${icon('clock')}ٹائمر چلائیں</button></div><h1>${esc(q.q)}</h1><div class="speaking-guide"><span>مرکزی موقف</span><i>←</i><span>دلیل یا مثال</span><i>←</i><span>نتیجہ یا ضروری حد</span></div><button class="btn primary reveal-button" id="reveal-answer">نمونہ جواب دیکھیے ${icon('book')}</button><div id="practice-answer" hidden>${answerHTML(q)}<div class="self-assess"><p>اپنے جواب سے موازنہ کیجیے</p><div><button class="btn assess-review" id="practice-review">${icon('repeat')}مزید مشق درکار ہے</button><button class="btn assess-known" id="practice-known">${icon('check')}اعتماد سے جواب دیا</button></div></div></div><button class="btn subtle practice-next" id="practice-next" hidden>${practiceIndex===practicePool.length-1?'مشق کا خلاصہ':'اگلا سوال'}${icon('arrow')}</button></article>`;$('#reveal-answer').onclick=()=>{revealed=true;clearInterval(timer);$('#practice-answer').hidden=false;$('#reveal-answer').hidden=true;$('#practice-next').hidden=false;$('#timer-toggle').disabled=true};$('#timer-toggle').onclick=()=>{if(timer){clearInterval(timer);timer=null;$('#timer-toggle').innerHTML=icon('clock')+'جاری رکھیں';return}$('#timer-toggle').innerHTML=icon('clock')+'روک دیں';timer=setInterval(()=>{remaining--;$('#timer-label').textContent=String(Math.floor(remaining/60)).padStart(2,'0')+':'+String(remaining%60).padStart(2,'0');if(remaining<=0){clearInterval(timer);timer=null;$('#timer-toggle').disabled=true;toast('وقت مکمل؛ جواب سے اپنا موازنہ کیجیے۔')}},1000)};$('#practice-review').onclick=()=>{assess(q,'review');$('#practice-review').classList.add('chosen');$('#practice-known').classList.remove('chosen')};$('#practice-known').onclick=()=>{assess(q,'known');$('#practice-known').classList.add('chosen');$('#practice-review').classList.remove('chosen')};$('#practice-next').onclick=()=>{if(practiceIndex<practicePool.length-1){practiceIndex++;renderPractice();window.scrollTo(0,0)}else practiceSummary()};$('#exit-practice').onclick=e=>{e.preventDefault();clearInterval(timer);practicePool=[];practiceSetup()}}
function practiceSummary(){clearInterval(timer);const known=practicePool.filter(isKnown).length;$('#main').innerHTML=heading('مسلسل کوشش، بہتر گفتگو','مشق مکمل ہوگئی','اپنی تیاری کے فیصلے اور پیش رفت اسی براؤزر میں محفوظ ہیں۔')+`<div class="practice-summary"><div class="summary-check">${icon('check')}</div><h2>${num(practicePool.length)} سوالات کی مشق</h2><p>${num(known)} سوالات پر آپ نے اعتماد ظاہر کیا۔ باقی سوالات دوبارہ دیکھ کر اپنی دلیل اور مثال بہتر بنائیے۔</p><div class="summary-actions"><a class="btn primary" href="#review">دہرائی دیکھیے ${icon('arrow')}</a><button class="btn subtle" id="practice-again">نئی مشق</button></div></div>`;$('#practice-again').onclick=practiceSetup;practicePool=[];updateProgress()}
function progressPage(){const known=ALL.filter(isKnown).length,review=ALL.filter(q=>progress[q.id]?.status==='review').length;const days=Object.keys(history).filter(d=>history[d]?.length).length;$('#main').innerHTML=heading('ہر قدم کی قدر کیجیے','آپ کی پیش رفت','یہ آپ کی خود جانچ پر مبنی پیش رفت ہے؛ رسمی امتحان کے نمبر نہیں۔')+`<div class="progress-stats"><div><span>${icon('check')}</span><b>${num(known)}</b><p>تیار شدہ سوالات</p></div><div><span>${icon('repeat')}</span><b>${num(review)}</b><p>دہرائی درکار</p></div><div><span>${icon('sun')}</span><b>${num(days)}</b><p>فعال مطالعے کے دن</p></div></div><div class="progress-subjects">${SUBJECTS.map(s=>`<a href="#subject/${s.id}" class="subject-progress" style="--subject:${s.color}"><span class="subject-symbol">${icon(s.icon)}</span><div><h2>${s.title}</h2><p>${num(s.questions.filter(isKnown).length)} از ${num(s.questions.length)} سوالات</p><div class="progress-track"><i style="width:${percent(s)}%"></i></div></div><b>${num(percent(s))}٪</b></a>`).join('')}</div><section class="activity-card"><h2>گزشتہ سات دن</h2><div class="activity-days">${Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-6+i);const key=d.toLocaleDateString('en-CA'),n=history[key]?.length||0;return `<div><div class="activity-column"><i style="height:${Math.max(3,Math.min(100,n/settings.goal*100))}%;opacity:${n?1:.18}"></i></div><b>${num(n)}</b><small>${d.toLocaleDateString('ur-PK',{weekday:'short'})}</small></div>`}).join('')}</div></section>`}
function settingsPage(){current=null;$('#main').innerHTML=heading('اپنے انداز کا مطالعہ','ترتیبات','آرام دہ خواندگی اور آپ کی ذاتی تیاری کے اختیارات۔')+`<div class="settings-grid"><section class="settings-card"><h2>${icon('sun')}رنگ اور خواندگی</h2><label>رنگوں کا انداز<select id="setting-theme"><option value="light">دن — روشن اور واضح</option><option value="dark">رات — گہرا پس منظر، سفید متن</option></select></label><label>اردو خط<select id="setting-font"><option value="nastaliq">جمیل نوری نستعلیق</option></select></label><label>متن کا حجم <b id="font-value">${num(settings.size)}</b><input id="setting-size" type="range" min="20" max="34" step="1" value="${settings.size}"></label><label class="check-label"><input id="setting-highlight" type="checkbox" ${settings.highlight?'checked':''}>اہم اصطلاحات نمایاں کریں</label><div class="type-preview">علم کی پختگی، فہم اور مسلسل مطالعے سے آتی ہے۔</div></section><section class="settings-card"><h2>${icon('chart')}مطالعے کا ہدف</h2><label>روزانہ سوالات کی تعداد<select id="setting-goal">${[3,5,10,15,20].map(n=>`<option value="${n}">${num(n)} سوالات</option>`).join('')}</select></label><p>ایک سوال کو سمجھ کر اپنے الفاظ میں جواب دینا، کئی جوابات سرسری پڑھنے سے زیادہ مفید ہے۔</p><div class="settings-note">${icon('info')}دہرائی کی تجویز آپ کے خود درج کیے گئے اعتماد کے مطابق وقفہ بڑھاتی ہے۔</div></section><section class="settings-card"><h2>${icon('download')}اپنا ریکارڈ محفوظ رکھیے</h2><p>پیش رفت، نوٹس اور محفوظ سوالات اسی آلے اور براؤزر میں رہتے ہیں۔ دوسرے آلے پر لے جانے کے لیے ریکارڈ برآمد کریں۔</p><div class="backup-buttons"><button class="btn primary" id="export-backup">ریکارڈ ڈاؤن لوڈ کریں</button><label class="btn subtle import-label">ریکارڈ واپس لائیں<input type="file" id="import-backup" accept="application/json,.json"></label></div><small>آپ کے جوابات یا نوٹس کسی سرور پر ارسال نہیں کیے جاتے۔</small></section><section class="settings-card reset-card"><h2>نئی شروعات</h2><p>صرف اسی براؤزر کی پیش رفت، نوٹس اور محفوظ سوالات صاف ہوں گے۔ پہلے اپنا ریکارڈ ڈاؤن لوڈ کر لیجیے۔</p><button class="btn danger" id="reset-progress">ذاتی ریکارڈ صاف کریں</button></section></div>`;
$('#setting-theme').value=settings.theme;$('#setting-font').value=settings.font;$('#setting-goal').value=settings.goal;const bind=(id,key,fn)=>{$(id).onchange=e=>{settings[key]=fn(e.target);save('settings',settings);applySettings()}};bind('#setting-theme','theme',e=>e.value);bind('#setting-font','font',e=>e.value);bind('#setting-goal','goal',e=>Number(e.value));bind('#setting-highlight','highlight',e=>e.checked);$('#setting-size').oninput=e=>{settings.size=Number(e.target.value);$('#font-value').textContent=num(settings.size);applySettings();save('settings',settings)};$('#export-backup').onclick=()=>downloadJSON({version:1,exportedAt:new Date().toISOString(),progress,bookmarks,notes,settings,history,last},'Al-Hayat-Study-Backup.json');$('#import-backup').onchange=importBackup;$('#reset-progress').onclick=()=>{if(!window.confirm('کیا آپ واقعی اس براؤزر کا تمام ذاتی ریکارڈ صاف کرنا چاہتے ہیں؟ یہ عمل واپس نہیں ہوسکے گا۔'))return;progress={};bookmarks=[];notes={};history={};last=null;for(const [k,v]of Object.entries({progress,bookmarks,notes,history,last}))save(k,v);updateProgress();toast('ذاتی ریکارڈ صاف ہوگیا۔')}}
function downloadJSON(data,name){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function importBackup(e){try{const f=e.target.files[0];if(!f)return;if(f.size>5e6)throw Error('size');const d=JSON.parse(await f.text());if(d.version!==1||!d.progress||Array.isArray(d.progress)||typeof d.progress!=='object'||!Array.isArray(d.bookmarks)||!d.notes||typeof d.notes!=='object')throw Error('format');if(!window.confirm('اس فائل کا ریکارڈ موجودہ پیش رفت اور نوٹس کی جگہ محفوظ ہوگا۔ جاری رکھیں؟'))return;const ids=new Set(ALL.map(q=>q.id));progress=Object.fromEntries(Object.entries(d.progress).filter(([id,v])=>ids.has(id)&&v&&['known','review'].includes(v.status)).map(([id,v])=>[id,{status:v.status,box:Math.max(0,Math.min(4,Number(v.box)||0)),due:Number(v.due)||Date.now(),updated:Number(v.updated)||Date.now()}]));bookmarks=[...new Set(d.bookmarks.filter(id=>ids.has(id)))];notes=Object.fromEntries(Object.entries(d.notes).filter(([id,v])=>ids.has(id)&&typeof v==='string'));history={};if(d.history&&typeof d.history==='object')for(const [day,arr]of Object.entries(d.history)){if(/^\d{4}-\d{2}-\d{2}$/.test(day)&&Array.isArray(arr))history[day]=[...new Set(arr.filter(id=>ids.has(id)))]}last=ids.has(d.last)?d.last:null;for(const [k,v]of Object.entries({progress,bookmarks,notes,history,last}))save(k,v);updateProgress();toast('مطالعے کا ریکارڈ بحال ہوگیا۔')}catch{toast('فائل درست مطالعہ ریکارڈ نہیں ہے۔')}finally{e.target.value=''}}
function about(){current=null;$('#main').innerHTML=heading('علمی تیاری کا ایک منظم راستہ','الحیات مرکز علومِ اسلامیہ','فہم، تحقیق اور شائستہ علمی مکالمے کے لیے۔')+`<section class="about-card"><div class="about-brand">ح</div><h2>Prepared by Dr. Imran Hayat</h2><p class="author-role" dir="ltr">Lecturer in Islamic Studies, University of Education, Lahore</p><p>یہ تعلیمی ذخیرہ علومِ اسلامیہ کے بنیادی اور اہم مباحث کو مربوط اردو سوالات و جوابات کے ذریعے پیش کرتا ہے۔ مقصد صرف جواب یاد کرنا نہیں، بلکہ مسئلہ سمجھنا، دلیل پہچاننا اور واضح علمی گفتگو کی تیاری ہے۔</p><a class="btn primary" href="https://drimranhayat.com" target="_blank" rel="noopener noreferrer">Visit my website ↗</a></section><div class="about-columns"><section class="settings-card"><h2>مطالعے کا مؤثر طریقہ</h2><ol><li>مضمون اور متعلقہ سوال منتخب کریں۔</li><li>جواب کا مرکزی موقف، دلیل اور ضروری حد سمجھیں۔</li><li>جواب بند کرکے اپنے الفاظ میں کہیے۔</li><li>اپنی تیاری درج کریں اور دہرائی کیجیے۔</li></ol></section><section class="settings-card"><h2>مواد اور علمی دائرہ</h2><p>فراہم کردہ آٹھ فائلوں کے تمام ${num(ALL.length)} سوالات و جوابات شامل ہیں۔ مراجع متعلقہ سوال یا مضمون کے ساتھ دستیاب ہیں۔ سوالات علمی اہمیت کے لحاظ سے منتخب ہیں؛ یہ انٹرویوز کی شماریاتی تکرار کی درجہ بندی نہیں۔</p><p>اختلافی مسائل میں اصل مصادر اور اہلِ تخصص سے مراجعت مفید ہے۔ ویب سائٹ کی نمایاں اصطلاحات صرف مطالعے کی سہولت ہیں؛ اصل عبارت تبدیل نہیں کی گئی۔</p></section></div>`}
function notFound(){$('#main').innerHTML=empty('یہ صفحہ نہیں ملا','مضامین کی فہرست سے اپنا مطالعہ دوبارہ شروع کیجیے۔')}
function route(){if($('#outline-dialog')?.open)$('#outline-dialog').close();clearInterval(timer);timer=null;closeMenu();focus=false;document.body.classList.remove('focus-mode');$('#main').style.removeProperty('--subject');const [view='home',sid,qid]=location.hash.replace(/^#/,'').split('/');setActive(view,sid);current=null;if(view==='home'||!view)home();else if(view==='subject')subject(sid);else if(view==='read')reader(sid,qid);else if(view==='bookmarks'||view==='review')collection(view);else if(view==='practice'){practicePool=[];practiceSetup()}else if(view==='progress')progressPage();else if(view==='settings')settingsPage();else if(view==='about')about();else notFound();window.scrollTo(0,0);document.title=(view==='read'&&current?current.title:view==='subject'&&getSub(sid)?getSub(sid).title:'علومِ اسلامیہ')+' | الحیات';$('#main').focus({preventScroll:true})}
function openSearch(){const d=$('#search-dialog');if(!d.open)d.showModal();$('#search-input').focus();renderSearch()}
function renderSearch(){const text=$('#search-input').value,sid=$('#search-subject').value;let found=ALL.filter(q=>(!sid||q.subject===sid)&&matches(q,text));$('#search-count').textContent=num(found.length)+' نتائج';if(!text.trim()&&!sid){$('#search-results').innerHTML=`<div class="search-intro">${icon('search')}<h2>علمی سوال تک پہنچنے کا مختصر راستہ</h2><p>سوال اور جواب دونوں میں تلاش ہوتی ہے۔</p><div class="suggestions">${['توحید','اجتہاد','اسبابِ نزول','نظمِ قرآن','سیرت'].map(t=>`<button data-suggestion="${t}">${t}</button>`).join('')}</div></div>`;$$('[data-suggestion]').forEach(b=>b.onclick=()=>{$('#search-input').value=b.dataset.suggestion;renderSearch()});return}$('#search-results').innerHTML=found.length?found.slice(0,80).map(q=>{const s=getSub(q.subject);return `<a class="search-result" href="#read/${q.subject}/${q.id}" style="--subject:${s.color}"><span>${s.title} • ${esc(q.title)}</span><h3>${esc(q.q)}</h3><p>${esc(q.a.slice(0,190))}…</p></a>`}).join('')+(found.length>80?'<p class="search-more">پہلے ۸۰ نتائج دکھائے گئے ہیں۔ زیادہ واضح الفاظ یا مضمون منتخب کریں۔</p>':''):empty('کوئی نتیجہ نہیں ملا','املا بدل کر یا کم الفاظ کے ساتھ دوبارہ تلاش کیجیے۔');$$('.search-result').forEach(a=>a.onclick=()=>$('#search-dialog').close())}
initNav();applySettings();route();window.addEventListener('hashchange',route);$('#search-trigger').onclick=openSearch;$('#close-search').onclick=()=>$('#search-dialog').close();$('#search-input').oninput=renderSearch;$('#search-subject').onchange=renderSearch;$('#search-dialog').onclick=e=>{if(e.target===$('#search-dialog'))$('#search-dialog').close()};$('#theme-btn').onclick=()=>{settings.theme=settings.theme==='dark'?'light':'dark';save('settings',settings);applySettings()};$('#menu-btn').setAttribute('aria-expanded','false');$('#menu-btn').onclick=()=>{document.body.classList.toggle('menu-open');$('#menu-btn').setAttribute('aria-expanded',document.body.classList.contains('menu-open'));syncMenuA11y()};$('#close-outline').onclick=()=>$('#outline-dialog').close();$('#outline-dialog').onclick=e=>{if(e.target===$('#outline-dialog'))$('#outline-dialog').close()};$('#back-to-top').onclick=()=>window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});window.addEventListener('scroll',()=>{$('#back-to-top').hidden=scrollY<500},{passive:true});$('#sidebar-shade').onclick=closeMenu;window.addEventListener('resize',syncMenuA11y);$('.skip-link').onclick=e=>{e.preventDefault();$('#main').focus();$('#main').scrollIntoView()};
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch()}if(e.key==='Escape')closeMenu();if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)||$('#search-dialog').open)return;if(current&&location.hash.startsWith('#read/')&&!e.ctrlKey&&!e.metaKey){if(e.key.toLowerCase()==='b'){e.preventDefault();$('#bookmark-btn').click()}if(e.key==='ArrowLeft')$('.reader-pagination a:last-child:not(.disabled)')?.click();if(e.key==='ArrowRight')$('.reader-pagination a:first-child:not(.disabled)')?.click()}});
